scenario.en:
// Spec: if the cart fails validation, priceCart returns null.
function priceCart(cart) {
  if (!isValid(cart)) return null;   // invalid → null
  const total = sumPrices(cart);
  if (total > LIMIT) return null;    // over the limit → also null
  return { total };
}

// In the logs: priceCart(cart42) === null
// Reviewer: "cart42 must have failed validation."

scenario.ru:
// Спецификация: если корзина не проходит валидацию, priceCart возвращает null.
function priceCart(cart) {
  if (!isValid(cart)) return null;   // некорректна → null
  const total = sumPrices(cart);
  if (total > LIMIT) return null;    // выше лимита → тоже null
  return { total };
}

// В логах: priceCart(cart42) === null
// Ревьюер: «cart42 наверняка не прошла валидацию».
